package com.pablo.controlgastos;
import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.os.Bundle;import android.widget.*;import java.text.*;import java.util.*;import java.util.regex.*;
public class CreditCardsActivity extends Activity{
 LinearLayout list;CreditCardDb db;android.content.SharedPreferences p;int BG,TEXT,CARD,MUTED;
 public void onCreate(Bundle b){ThemePrefs.applyBaseTheme(this);super.onCreate(b);db=new CreditCardDb(this);p=getSharedPreferences(EmailSyncEngine.PREF,0);boolean l=ThemePrefs.isLight(this);BG=l?0xfff6f8f9:0xff0b1218;TEXT=l?0xff1f262c:0xfff2f5f7;CARD=l?Color.WHITE:0xff162029;MUTED=l?0xff5f6970:0xff9ea9b2;build();}
 TextView t(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(TEXT);v.setPadding(18,14,18,14);return v;}Button btn(String s){Button x=new Button(this);x.setText(s);x.setAllCaps(false);return x;}
 void build(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(20,55,20,20);r.setBackgroundColor(BG);r.addView(t("Tarjetas de crédito",26));LinearLayout a=new LinearLayout(this);Button cfg=btn("⚙ Correo"),sync=btn("↻ Leer estados"),help=btn("? Ayuda");a.addView(cfg,new LinearLayout.LayoutParams(0,-2,1));a.addView(sync,new LinearLayout.LayoutParams(0,-2,1));a.addView(help,new LinearLayout.LayoutParams(0,-2,1));r.addView(a);cfg.setOnClickListener(v->startActivity(new Intent(this,EmailSettingsActivity.class)));sync.setOnClickListener(v->sync());help.setOnClickListener(v->help());ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);sc.addView(list);r.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);refresh();}
 void help(){new AlertDialog.Builder(this).setTitle("Ayuda · Tarjetas de crédito").setMessage("La cuenta de correo, lista blanca, período y criterios de comparación ahora se configuran en Ajustes → Correo y lecturas.\n\nLa prioridad de esta pantalla es mostrar para cada compra la cuota actual, el total de cuotas, cuántas quedan y el monto de esa cuota.\n\nLos criterios de comparación de tarjeta sirven únicamente para identificar el GASTO correspondiente al pago total del estado. No modifican la lectura de compras o cuotas.\n\n‘Leer estados’ hace una lectura normal. Para reprocesar todo el período usá ‘Forzar lectura de estados’ dentro de Ajustes → Correo y lecturas.").setPositiveButton("Entendido",null).show();}
 void refresh(){list.removeAllViews();Cursor c=db.getReadableDatabase().rawQuery("SELECT c.name,c.last4,s.id,s.close_date,s.due_date,s.total,s.currency FROM cards c LEFT JOIN statements s ON s.card_id=c.id AND s.id=(SELECT MAX(x.id) FROM statements x WHERE x.card_id=c.id) ORDER BY c.id",null);while(c.moveToNext()){long sid=c.isNull(2)?-1:c.getLong(2);String name=c.getString(0),last=c.getString(1),due=sid<0?"":c.getString(4),cur=sid<0?"UYU":c.getString(6);double total=sid<0?0:c.getDouble(5);String z=name+" •••• "+last+(sid<0?"\nSin estado importado":"\nCierre: "+c.getString(3)+"   Vence: "+due+"\nPago contado: "+cur+" "+String.format(Locale.US,"%.2f",total)+payment(total,cur,due,last));TextView x=t(z,17);x.setBackgroundColor(CARD);x.setOnClickListener(v->{if(sid>0)statement(sid,name,last);});list.addView(x);}c.close();if(list.getChildCount()==0)list.addView(t("Todavía no hay tarjetas. Al leer un estado se agregará automáticamente.",15));}
 String payment(double total,String cur,String due,String last4){boolean am=p.getBoolean("card_cmp_amount",p.getBoolean("pay_amount",true)),tx=p.getBoolean("card_cmp_text",p.getBoolean("pay_text",true)),cu=p.getBoolean("card_cmp_currency",true),date=p.getBoolean("card_cmp_due_date",false),last=p.getBoolean("card_cmp_last4",false);if(!am&&!tx&&!cu&&!date&&!last)return"\nIdentificación de pago desactivada";ExpenseDb e=new ExpenseDb(this);Cursor c=e.getReadableDatabase().rawQuery("SELECT amount,description,currency,COALESCE(original_ts,ts),original_text FROM tx WHERE type='GASTO' ORDER BY ts DESC LIMIT 500",null);try{long dueTs=parseDue(due);while(c.moveToNext()){String d=(c.getString(1)==null?"":c.getString(1))+" "+(c.getString(4)==null?"":c.getString(4));String up=d.toUpperCase(Locale.ROOT);if(am&&Math.abs(c.getDouble(0)-total)>.01)continue;if(tx&&!(up.contains("PAGO TC")||up.contains("PAGO DE TARJETA")))continue;if(cu&&!cur.equalsIgnoreCase(c.getString(2)))continue;if(date&&dueTs>0&&Math.abs(c.getLong(3)-dueTs)>15L*24*3600*1000)continue;if(last&&!d.contains(last4))continue;return"\n✓ Pago de tarjeta identificado";}return"\nPago aún no identificado";}finally{c.close();e.close();}}
 long parseDue(String s){if(s==null)return 0;for(String f:new String[]{"dd/MM/yyyy","dd/MM/yy"})try{SimpleDateFormat d=new SimpleDateFormat(f,Locale.US);d.setLenient(false);return d.parse(s).getTime();}catch(Exception ignored){}return 0;}
 String installmentInfo(String raw){if(raw==null)return"";Matcher m=Pattern.compile("(?i)CUOTA\\s*0*(\\d{1,2})/0*(\\d{1,2})").matcher(raw);if(!m.find())return raw;int cur=Integer.parseInt(m.group(1)),tot=Integer.parseInt(m.group(2)),left=Math.max(0,tot-cur);return"Cuota "+cur+" de "+tot+" · "+left+" restante"+(left==1?"":"s");}
 void statement(long sid,String name,String last){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);TextView h=t("Cuotas y montos del estado\nLa app prioriza la cuota actual, el total de cuotas, cuántas quedan y el monto de cada cuota.",14);h.setTextColor(MUTED);f.addView(h);Cursor c=db.getReadableDatabase().rawQuery("SELECT tx_date,description,installment,amount,currency FROM installments WHERE statement_id=? ORDER BY id",new String[]{""+sid});while(c.moveToNext()){String inst=installmentInfo(c.getString(2));String line=c.getString(1)+"\n"+(inst.isEmpty()?"Compra sin cuota detectada":inst)+"\nMonto: "+c.getString(4)+" "+String.format(Locale.US,"%.2f",c.getDouble(3))+"   ·   "+c.getString(0);TextView v=t(line,15);v.setBackgroundColor(CARD);f.addView(v,new LinearLayout.LayoutParams(-1,-2));}c.close();ScrollView s=new ScrollView(this);s.addView(f);new AlertDialog.Builder(this).setTitle(name+" •••• "+last+" — cuotas").setView(s).setPositiveButton("Cerrar",null).show();}
 void sync(){ProgressDialog d=ProgressDialog.show(this,"Tarjetas","Leyendo estados nuevos…",true,false);new Thread(()->{try{EmailSyncEngine.Result r=EmailSyncEngine.readCards(this,false);runOnUiThread(()->{d.dismiss();refresh();Toast.makeText(this,"Estados actualizados: "+r.imported,Toast.LENGTH_LONG).show();});}catch(Exception ex){runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(this).setTitle("No se pudo leer el correo").setMessage(ex.getMessage()+"\n\nRevisá Ajustes → Correo y lecturas.").setPositiveButton("Aceptar",null).show();});}}).start();}
}
